export interface OrganizationSummary {
  readonly organization: Organization;
  readonly usage: OrganizationUsage;
  readonly memberCount: number;
  readonly projectCount: number;
  /** `null` while the workspace is writable. The shell reads this for its banner. */
  readonly lockReason: WorkspaceLockReason | null;
}

/**
 * Read-only lock for a workspace whose subscription is not in good standing.
 *
 * Billing, deletion, notification housekeeping and Taskflow's own jobs stay
 * writable; every member write asks `lockReasonFor` first.
 */
import type { Subscription, WorkspaceLockReason } from "@/types/billing";
import type { OrgId } from "@/types/common";

export class WorkspaceLockedError extends Error {
  readonly code = "plan_limit_exceeded" as const;
  readonly orgId: OrgId;
  readonly reason: WorkspaceLockReason;

  constructor(orgId: OrgId, reason: WorkspaceLockReason) {
    super(`This workspace is read-only (${reason}).`);
    this.name = "WorkspaceLockedError";
    this.orgId = orgId;
    this.reason = reason;
  }
}

/**
 * Pure lock rule, evaluated against the subscription row as stored.
 *
 * No row, or `active`, is writable. `past_due` is locked immediately.
 * `trialing` locks at the period end (that instant included). `canceled`
 * locks when `cancelAt` is reached; a cancellation dated later stays
 * writable until then, and a missing cancellation date counts as now.
 */
export function lockReasonFor(
  subscription: Subscription | null,
  now: Date = new Date(),
): WorkspaceLockReason | null {
  if (subscription === null || subscription.status === "active") return null;

  if (subscription.status === "past_due") return "past_due";

  if (subscription.status === "trialing") {
    return reached(subscription.currentPeriodEnd, now) ? "trial_ended" : null;
  }

  if (subscription.cancelAt === null || reached(subscription.cancelAt, now)) {
    return "canceled";
  }

  return null;
}

/** True when `stamp` is at or before `now`. */
function reached(stamp: string, now: Date): boolean {
  return Date.parse(stamp) <= now.getTime();
}

