 * immediately after the permission check, so an earlier refusal (wrong
 * organization, insufficient role, invalid token) still wins.
 */
export async function assertWorkspaceWritable(
  orgId: OrgId,
  now?: Date,
): Promise<void> {
  const reason = lockReasonFor(
    await subscriptionRepo.findSubscription(orgId),
