/**
 * Shell banner shown while a workspace is read-only.
 *
 * Billing stays available — it is the way out of the lock — so owners get a
 * link to the billing settings and everyone else is told to ask one.
 */
import Link from "next/link";
import type { ReactElement } from "react";
import { Alert } from "@/components/ui/alert";
import { can } from "@/lib/permissions";
import { settingsPath } from "@/lib/url";
import type { WorkspaceLockReason } from "@/types/billing";
import type { Actor } from "@/types/member";
import { billingResource } from "../permission/resources";

export type WorkspaceLockBannerProps = {
  reason: WorkspaceLockReason | null;
  orgSlug: string;
  actor: Actor;
};

const COPY: Readonly<Record<WorkspaceLockReason, string>> = {
  past_due: "This workspace is read-only because the subscription is past due.",
  canceled: "This workspace is read-only because the subscription is canceled.",
  trial_ended: "This workspace is read-only because the trial has ended.",
};

export function WorkspaceLockBanner(
  props: WorkspaceLockBannerProps,
): ReactElement | null {
  const { reason, orgSlug, actor } = props;
  if (reason === null) return null;

  const mayManageBilling = can(
    actor,
    "org:manage_billing",
    billingResource(actor.orgId),
  );

  return (
    <Alert tone="warning" title="Workspace is read-only">
      {COPY[reason]}{" "}
      {mayManageBilling ? (
        <Link
          href={settingsPath(orgSlug, "billing")}
          className="font-medium underline"
        >
          Update billing
        </Link>
      ) : (
        "Ask an owner to update billing."
      )}
    </Alert>
  );
}

